command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1";$candidate="bf40a11f5f649f3a5c19389d3a4f792996c29e04";$branch="work/unc-network-metadata-sort-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network metadata build2 fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network metadata build2"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network metadata build2 candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-metadata-build2-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network metadata build2 worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network metadata build2 diff check failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "network metadata build2 Release build failed"}
 & python -u -X utf8 .\tests\winui\test_metadata_sort_gui.py --configuration Release --force-isolated-metadata
 if($LASTEXITCODE -ne 0){throw "network metadata build2 focused GUI failed"}
 Write-Host "NETWORK_METADATA_BUILD2_DIFF_CHECK=PASS"
 Write-Host "NETWORK_METADATA_BUILD2_RELEASE=PASS"
 Write-Host "NETWORK_METADATA_BUILD2_ISOLATED_GUI=PASS"
 Write-Host "NETWORK_METADATA_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
